export async function recoverOnboardingStep(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){const ctx=actorContext(actor),input=recoverInput.parse(raw),existing=await withTenant(deps.db,ctx.organizationId,async tx=>{const row=await new OnboardingRepository(tx,ctx.organizationId).byNonce(input.idempotencyKey);if(row){if(row.createdBy!==ctx.actorId||input.sessionId&&row.sessionId!==input.sessionId)throw new OnboardingAccessError();await sessionContext(ctx,tx,row.sessionId);return row;}if(input.sessionId)await sessionContext(ctx,tx,input.sessionId);else await authority(ctx,tx,[{action:"view",resource:resource(ctx.organizationId),organizationOnly:true}]);return null;});await spendRead(ctx,deps,existing?.sessionId??input.sessionId);return withTenant(deps.db,ctx.organizationId,async tx=>{const row=await new OnboardingRepository(tx,ctx.organizationId).byNonce(input.idempotencyKey);if(!row){if(input.sessionId)await sessionContext(ctx,tx,input.sessionId);else await authority(ctx,tx,[{action:"view",resource:resource(ctx.organizationId),organizationOnly:true}]);return{recorded:false,revision:null};}if(input.sessionId&&row.sessionId!==input.sessionId)throw new OnboardingAccessError();return{recorded:true,revision:await recoverExisting(ctx,tx,row,deps)};});}
export async function readOnboardingSession(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){return onboardingReadSchema.parse(await readRecordInternal(actor,raw,deps,"OWNER"));}
export async function readOnboardingRecord(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){return readRecordInternal(actor,raw,deps);}
async function readRecordInternal(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies,expectedStep?:"OWNER"|"PROPERTY"|"OPERATING_PROFILE"){
 const ctx=actorContext(actor),input=onboardingReadInputSchema.parse(raw);await spendRead(ctx,deps,input.sessionId);
 return withTenant(deps.db,ctx.organizationId,async tx=>{
  const base=await sessionContext(ctx,tx,input.sessionId,"view",true),selected=input.revisionId?await base.repository.byId(input.revisionId):base.row;
  if(!selected||selected.sessionId!==input.sessionId||expectedStep&&selected.step!==expectedStep)throw new OnboardingAccessError();
  if(!["OWNER","PROPERTY","OPERATING_PROFILE"].includes(selected.step))throw new OnboardingConfigurationError();
  if(base.row.propertyId)await propertyRead(ctx,tx,base.row.propertyId,base.row.ownerId,false,true);
  await authority(ctx,tx,[{action:"view",resource:resource(ctx.organizationId,selected)},{action:"export",resource:{...resource(ctx.organizationId,selected),dataClass:"personal"}}]);await ownerRead(ctx,tx,selected.ownerId,false,true);if(selected.propertyId)await propertyRead(ctx,tx,selected.propertyId,selected.ownerId,false,true);
  const payload=selected.step==="OPERATING_PROFILE"?retainedOperating(selected,deps.env):selected.step==="PROPERTY"?retainedProperty(selected,deps.env):retained(selected,deps.env),rows=await base.repository.history(input.sessionId,input.before),history=rows.slice(0,20).map(row=>receipt(row));
  await writeAuditEvent(tx,{organizationId:ctx.organizationId,actorId:ctx.actorId,action:"onboarding.session_read",resourceType:"onboarding",resourceId:input.sessionId,after:{sessionId:input.sessionId,revisionId:selected.id,count:history.length},requestId:deps.requestId??randomUUID(),occurredAt:await base.repository.clock()});
  const final=await sessionContext(ctx,tx,input.sessionId,"view",true);if(final.row.id!==base.row.id)throw new OnboardingConflictError();if(final.row.propertyId)await propertyRead(ctx,tx,final.row.propertyId,final.row.ownerId,false,true);
  await authority(ctx,tx,[{action:"view",resource:resource(ctx.organizationId,selected)},{action:"export",resource:{...resource(ctx.organizationId,selected),dataClass:"personal"}}]);await ownerRead(ctx,tx,selected.ownerId,false,true);if(selected.propertyId)await propertyRead(ctx,tx,selected.propertyId,selected.ownerId,false,true);
  const position=onboardingSteps.findIndex(step=>step===final.row.step);if(position<0)throw new OnboardingConfigurationError();
  const common={sessionId:input.sessionId,current:receipt(final.row),selected:receipt(selected),owner:payload.originalOwner,reason:payload.command.reason,history,next:rows.length>20?rows[19].number:null,completed:onboardingSteps.slice(0,position+1),nextStep:onboardingSteps[position+1]??null};
  const data="originalOperatingProfile"in payload?onboardingOperatingReadSchema.parse({...common,draft:canonicalOnboardingOperatingDraft({sessionId:payload.command.sessionId,previousRevisionId:payload.command.previousRevisionId,step:payload.command.step,target:payload.command.target}),property:payload.originalProperty,previousOperatingProfile:payload.previousOperatingProfile,operatingProfile:payload.originalOperatingProfile,operatingRule:nativeOperatingRuleProjection(payload.operatingRule)}):"originalProperty"in payload?onboardingPropertyReadSchema.parse({...common,draft:canonicalOnboardingPropertyDraft({sessionId:payload.command.sessionId,previousRevisionId:payload.command.previousRevisionId,step:payload.command.step,target:payload.command.target}),property:payload.originalProperty,initialOperatingProfile:payload.initialOperatingProfile}):onboardingReadSchema.parse({...common,draft:canonicalOnboardingDraft({sessionId:payload.command.sessionId,previousRevisionId:payload.command.previousRevisionId,step:payload.command.step,target:payload.command.target})});
  const projection=present({...ctx.authContext,visibleDataClasses:new Set(["personal"]as const)},"export",{...resource(ctx.organizationId,selected),dataClass:"personal",data},{},await base.repository.clock());return selected.step==="OPERATING_PROFILE"?onboardingOperatingReadSchema.parse(projection):onboardingRecordSchema.parse(projection);
 });
}


function readCursor(actor:AccountActorContext,filter:string,raw?:string){if(!raw)return null;try{const value=cursorSchema.parse(JSON.parse(decryptSecret(raw)));if(value.organizationId!==actor.organizationId||value.actorId!==actor.actorId||value.filter!==filter)throw new OnboardingConflictError();return value;}catch{throw new OnboardingConflictError();}}
function cursor(actor:AccountActorContext,filter:string,asOf:Date,beforeId:string,beforeAt?:Date){return encryptSecret(JSON.stringify({protocol,organizationId:actor.organizationId,actorId:actor.actorId,filter,asOf:asOf.toISOString(),beforeId,...beforeAt?{beforeAt:beforeAt.toISOString()}:{} }));}
export async function readOnboardingDirectory(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){const ctx=actorContext(actor),input=directoryInput.parse(raw),filter=commandFingerprint({protocol,operation:"DIRECTORY"}),before=readCursor(ctx,filter,input.cursor);if(before&&!before.beforeAt)throw new OnboardingConflictError();await spendRead(ctx,deps);return withTenant(deps.db,ctx.organizationId,async tx=>{
 const repository=new OnboardingRepository(tx,ctx.organizationId);await authority(ctx,tx,[{action:"view",resource:resource(ctx.organizationId),organizationOnly:true}]);const asOf=before?new Date(before.asOf):await repository.clock(),page=await repository.directory(asOf,before?{createdAt:new Date(before.beforeAt!),sessionId:before.beforeId}:undefined),rows=await repository.revisionRows(page.slice(0,20).map(row=>row.revisionId)),byId=new Map(rows.map(row=>[row.id,row])),items=page.slice(0,20).map(item=>{const row=byId.get(item.revisionId);if(!row)throw new OnboardingConflictError();return receipt(row);});
 await writeAuditEvent(tx,{organizationId:ctx.organizationId,actorId:ctx.actorId,action:"onboarding.directory_read",resourceType:"onboarding",resourceId:null,after:{count:items.length},requestId:deps.requestId??randomUUID(),occurredAt:await repository.clock()});await authority(ctx,tx,[{action:"view",resource:resource(ctx.organizationId),organizationOnly:true}]);const final=new Map((await repository.currentHeads(page.slice(0,20).map(item=>item.sessionId))).map(row=>[row.sessionId,row.id]));if(page.slice(0,20).some(item=>final.get(item.sessionId)!==item.revisionId))throw new OnboardingConflictError();return onboardingDirectorySchema.parse({items,next:page.length>20?cursor(ctx,filter,asOf,page[19].sessionId,page[19].createdAt):null});
});}
export async function readOnboardingOwners(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){const ctx=actorContext(actor),input=onboardingChoicesInputSchema.parse(raw),filter=commandFingerprint({protocol,operation:"OWNERS",query:input.query,sessionId:input.sessionId??null}),before=readCursor(ctx,filter,input.cursor);if(before?.beforeAt)throw new OnboardingConflictError();await spendRead(ctx,deps,input.sessionId);return withTenant(deps.db,ctx.organizationId,async tx=>{
 const repository=new OnboardingRepository(tx,ctx.organizationId),current=input.sessionId?(await sessionContext(ctx,tx,input.sessionId,"edit",true)).row:undefined,checks:CurrentAuthorityCheck[]=[{action:current?"edit":"create",resource:resource(ctx.organizationId,current),...current?{}:{organizationOnly:true}},{action:"export",resource:resource(ctx.organizationId,current),...current?{}:{organizationOnly:true}},{action:"view",resource:ownerResource(ctx.organizationId),organizationOnly:true},{action:"edit",resource:ownerResource(ctx.organizationId),organizationOnly:true}];await authority(ctx,tx,checks);const configured=await settings(tx,ctx.organizationId,await repository.clock());if(!configured.policy.owner_modes.includes("LINK"))throw new OnboardingConfigurationError();const asOf=before?new Date(before.asOf):await repository.clock(),rows=await nativeOnboardingOwnerChoices(tx,ctx.organizationId,input.query,before?.beforeId,asOf),selected=rows.slice(0,20),captured=new Map(selected.map(row=>[row.id,commandFingerprint(row)]));
 await writeAuditEvent(tx,{organizationId:ctx.organizationId,actorId:ctx.actorId,action:"onboarding.owner_choices_read",resourceType:"onboarding",resourceId:current?.sessionId??null,after:{count:selected.length},requestId:deps.requestId??randomUUID(),occurredAt:await repository.clock()});await authority(ctx,tx,checks);const final=new Map((await nativeOnboardingOwnerIdentityRows(tx,ctx.organizationId,selected.map(row=>row.id))).map(row=>[row.id,commandFingerprint(row)]));if(selected.some(row=>final.get(row.id)!==captured.get(row.id))||commandFingerprint((await settings(tx,ctx.organizationId,await repository.clock())).snapshot)!==commandFingerprint(configured.snapshot))throw new OnboardingConflictError();if(current&&(await repository.current(current.sessionId))?.id!==current.id)throw new OnboardingConflictError();return onboardingChoicesSchema.parse({owners:selected.map(row=>({id:row.id,displayName:row.displayName,email:row.email})),next:rows.length>20?cursor(ctx,filter,asOf,selected[19].id):null});
});}

/** Property sources are authorized before physical identities are loaded; every page has independent final fences. */
export async function readOnboardingProperties(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){
 const ctx=actorContext(actor),input=onboardingPropertyChoicesInputSchema.parse(raw);await spendRead(ctx,deps,input.sessionId);
 return withTenant(deps.db,ctx.organizationId,async tx=>{
  const base=await sessionContext(ctx,tx,input.sessionId,"edit",true),repository=base.repository,current=base.row;
  if(current.step!=="OWNER"&&current.step!=="PROPERTY")throw new OnboardingConflictError();
  await ownerRead(ctx,tx,current.ownerId);
  const ownerBefore=await nativeOnboardingOwnerWitness(tx,ctx.organizationId,current.ownerId);if(!ownerBefore)throw new OnboardingAccessError();
  const checks:CurrentAuthorityCheck[]=[{action:"view",resource:resource(ctx.organizationId,current)},{action:"edit",resource:resource(ctx.organizationId,current)},{action:"export",resource:{...resource(ctx.organizationId,current),dataClass:"personal"}},{action:"view",resource:ownerResource(ctx.organizationId,ownerBefore)}];
  const initial=await authority(ctx,tx,checks),configured=await settings(tx,ctx.organizationId,await repository.clock());
  if(!configured.policy.property_modes?.includes("LINK"))throw new OnboardingConfigurationError();
  const filter=commandFingerprint({protocol,operation:"PROPERTIES",sessionId:input.sessionId,ownerId:current.ownerId,revisionId:current.id,query:input.query,authorizationCap:captureAuthorizationCap(ctx.authContext)}),before=readCursor(ctx,filter,input.cursor);if(before?.beforeAt)throw new OnboardingConflictError();
  const asOf=before?new Date(before.asOf):await repository.clock(),page=await nativeOnboardingPropertyChoices(tx,ctx.organizationId,current.ownerId,input.query,before?.beforeId,asOf),scanned=page.slice(0,50),heads=await nativeOnboardingPropertyHeads(tx,ctx.organizationId,scanned.map(row=>row.id)),byId=new Map(heads.map(row=>[row.id,row]));
  const propertyChecks=(head:typeof heads[number]):CurrentAuthorityCheck[]=>["view","edit"].map(action=>({action:action as "view"|"edit",resource:propertyResource(ctx.organizationId,head,current.ownerId)}));
  const selected=scanned.filter(row=>{const head=byId.get(row.id);if(!head||!head.ownership.some(value=>value.ownerId===current.ownerId)||!["DRAFT","ONBOARDING"].includes(head.status))return false;try{assertAccountAuthorization(ctx,initial.stored,initial.now,propertyChecks(head),new OnboardingAccessError());return true;}catch(error){if(error instanceof OnboardingAccessError)return false;throw error;}}).slice(0,20);
  const rows=await nativeOnboardingPropertyRows(tx,ctx.organizationId,selected.map(row=>row.id)),identities=new Map(rows.map(row=>[row.id,row]));if(selected.some(row=>!identities.has(row.id)))throw new OnboardingConflictError();
  await writeAuditEvent(tx,{organizationId:ctx.organizationId,actorId:ctx.actorId,action:"onboarding.property_choices_read",resourceType:"onboarding",resourceId:current.sessionId,after:{count:selected.length},requestId:deps.requestId??randomUUID(),occurredAt:await repository.clock()});
  const final=await authority(ctx,tx,checks),fresh=new Map((await nativeOnboardingPropertyHeads(tx,ctx.organizationId,scanned.map(row=>row.id))).map(row=>[row.id,row])),ownerAfter=await nativeOnboardingOwnerWitness(tx,ctx.organizationId,current.ownerId);
  if(!ownerAfter||commandFingerprint(sourceSnapshot(ownerBefore))!==commandFingerprint(sourceSnapshot(ownerAfter))||scanned.some(row=>commandFingerprint(byId.get(row.id)??null)!==commandFingerprint(fresh.get(row.id)??null))||(await repository.current(current.sessionId))?.id!==current.id||commandFingerprint((await settings(tx,ctx.organizationId,await repository.clock())).snapshot)!==commandFingerprint(configured.snapshot))throw new OnboardingConflictError();
  for(const selectedHead of selected){const head=fresh.get(selectedHead.id);if(!head)throw new OnboardingConflictError();assertAccountAuthorization(ctx,final.stored,final.now,propertyChecks(head),new OnboardingAccessError());}
  const last=selected.length===20?selected[19]:scanned.at(-1),hasMore=Boolean(last)&&(page.length>50||scanned.some(row=>row.id>last!.id));
  return onboardingPropertyChoicesSchema.parse({properties:selected.map(item=>{const row=identities.get(item.id)!;return{id:row.id,name:row.name,addressLine1:row.addressLine1,city:row.city,status:row.status};}),next:hasMore?cursor(ctx,filter,asOf,last!.id):null});
 });
}

export async function reviewOnboardingRecordStep(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){const ctx=actorContext(actor),draft=canonicalOnboardingRecordDraft(raw);return draft.step==="OWNER"?reviewOnboardingStep(ctx,draft,deps):draft.step==="PROPERTY"?reviewOnboardingPropertyStep(ctx,draft,deps):reviewOnboardingOperatingStep(ctx,draft,deps);}
export async function admitOnboardingRecordStep(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){const ctx=actorContext(actor),command=canonicalOnboardingRecordCommand(raw);return command.step==="OWNER"?admitOnboardingStep(ctx,command,deps):command.step==="PROPERTY"?admitOnboardingPropertyStep(ctx,command,deps):admitOnboardingOperatingStep(ctx,command,deps);}
